```go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"

	"github.com/hashicorp/go-avropkg/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run main.go <filename> <struct>")
		os.Exit(1)
	}

	filename := os.Args[1]
	structName := os.Args[2]

	file, err := ioutil.ReadFile(filename)
	if err != nil {
		log.Fatalf("Could not read %s: %v", filename, err)
	}

	fset := token.NewFileSet()
	fileTree, err := parser.ParseFiles(fset, []byte(file), token.AllErrors)
	if err != nil {
		log.Fatalf("Failed to parse %s: %v", filename, err)
	}

	for _, decl := range fileTree.Decls {
		if d, ok := decl.(*ast.StructBody); ok && d.Name == structName {
			break
		}
	}

	if !ok {
		fmt.Printf("%q was not found\n", structName)
		return
	}

	var fields []*schema.FieldSpec
	for i, fieldDecl := range d.Fields.List {
		fieldType := reflect.TypeOf(fieldDecl.Type).Elem()

		switch fieldType.Kind() {
		case reflect.String:
			fields = append(fields, &schema.FieldSpec{
				Name:     string(fieldDecl.Names[0]),
				Type:     schema.TypeString,
				Description: "The value of this field.",
			})
		case reflect.Int64, reflect.Float64, reflect.Bool, reflect.Slice, reflect.Map:
			fields = append(fields, &schema.FieldSpec{
				Name:     string(fieldDecl.Names[0]),
				Type:     schema.TypePrimitive(fieldType.Kind()),
				Description: fmt.Sprintf(
					"The value of this field.\n\t%s",
					ast.NodeToString(&fieldDecl),
				),
			})
		default:
			continue // Skip unknown types
		}
	}

	schemaStr, err := schema.WriteSchema(schema.Spec{
		Fields: fields,
	})

	if err != nil {
		log.Fatalf("Failed to generate Avro schema: %v", err)
	}

	outfile := fmt.Sprintf("%s.avsc", structName)
	err = ioutil.WriteFile(outfile, []byte(schemaStr), 0644)
	if err != nil {
		log.Fatalf("Error writing to %s: %v", outfile, err)
	}

	fmt.Printf("Generated Avro schema saved to %s\n", outfile)
}
```

### Explanation:

1. **Command Line Argument Handling**: The program expects two command line arguments - the name of the Go source file and the name of the struct.

2. **Reading Source Code**: The program reads the content of the specified Go source file.

3. **Parsing Source Code**: Using `parser.ParseFiles`, it parses the source code into an AST (Abstract Syntax Tree).

4. **Struct Search**: Iterates through the parsed AST to find the struct with the desired name.

5. **Field Extraction**: For each field declared within the struct, it extracts the field type and generates an Avro schema definition based on its properties.

6. **Generating Schema String**: Constructs an Avro schema string using the generated fields.

7. **Writing Output**: Writes the Avro schema string to a file named `<struct>.avsc`.

